  const agent3Path = { p0: { x: 210, y: 730 }, p1: { x: 300, y: 730 }, p2: { x: 300, y: 540 }, p3: { x: 390, y: 540 } };

  const outPath1 = { p0: { x: 920, y: 420 }, p1: { x: 1100, y: 420 }, p2: { x: 1140, y: 260 }, p3: { x: 1320, y: 260 } };
  const outPath2 = { p0: { x: 957.2, y: 490 }, p1: { x: 1100, y: 490 }, p2: { x: 1140, y: 440 }, p3: { x: 1320, y: 440 } };
